CREATE TABLE employer_accounts (account_id TEXT PRIMARY KEY, legal_name TEXT NOT NULL, normalized_legal_name TEXT NOT NULL, alias_name TEXT, tax_classification TEXT NOT NULL, account_owner_id TEXT, account_status TEXT NOT NULL CHECK (account_status IN ('ACTIVE','INACTIVE','PROSPECT')), created_at TEXT NOT NULL, CHECK (length(account_id) > 0));

CREATE TABLE sales_opportunities (opportunity_id TEXT PRIMARY KEY, account_id TEXT NOT NULL, contract_id TEXT NOT NULL UNIQUE, requesting_unit_id TEXT NOT NULL, requesting_contact_person_id TEXT, opportunity_owner_id TEXT, opportunity_owner_status TEXT NOT NULL CHECK (opportunity_owner_status IN ('ASSIGNED','UNASSIGNED','PENDING_REASSIGNMENT')), submission_status TEXT NOT NULL CHECK (submission_status IN ('DRAFT','INTAKE_QUEUE','LEGAL_REVIEW','CLOSED_WON','CLOSED_LOST')), requested_deadline TEXT, controlling_quote_id TEXT, displayed_quote_total_cents INTEGER, pricing_basis_code TEXT, pricing_approval_reference TEXT, contract_start_date TEXT, contract_end_date TEXT, submission_note TEXT, created_at TEXT NOT NULL, FOREIGN KEY (account_id) REFERENCES employer_accounts(account_id), CHECK (displayed_quote_total_cents IS NULL OR displayed_quote_total_cents >= 0));

CREATE TABLE quote_line_items (quote_line_id TEXT PRIMARY KEY, opportunity_id TEXT NOT NULL, quote_id TEXT NOT NULL, quote_version INTEGER NOT NULL, service_code TEXT NOT NULL, service_description TEXT NOT NULL, quantity INTEGER NOT NULL CHECK (quantity > 0), unit_price_cents INTEGER NOT NULL CHECK (unit_price_cents >= 0), extended_amount_cents INTEGER NOT NULL CHECK (extended_amount_cents >= 0), line_status TEXT NOT NULL CHECK (line_status IN ('ACTIVE','SUPERSEDED','VOID')), duplicate_of_line_id TEXT, pricing_attribute_status TEXT NOT NULL CHECK (pricing_attribute_status IN ('COMPLETE','INCOMPLETE')), finance_worktag_status TEXT NOT NULL CHECK (finance_worktag_status IN ('CODED','PENDING','NOT_REQUIRED')), created_at TEXT NOT NULL, FOREIGN KEY (opportunity_id) REFERENCES sales_opportunities(opportunity_id), FOREIGN KEY (duplicate_of_line_id) REFERENCES quote_line_items(quote_line_id), CHECK (extended_amount_cents = quantity * unit_price_cents));